class Emitter {
  constructor() {
    this.handlers = {};
  }
  on(evt, fn) {
    (this.handlers[evt] ??= []).push(fn);
  }
  off(evt, fn) {
    this.handlers[evt]?.filter((h) => h !== fn);
  }
  emit(evt, data) {
    this.handlers[evt]?.forEach((h) => h(data));
  }
}
